const emb = $json.embedding.values;
const vec = '[' + emb.join(',') + ']';
const req = $('Requete de recherche').item.json;
const keywords = String(req.search_query).replace(/[,'\"]/g, ' ').trim();
return [{ json: { vec, keywords, question: req.question, search_query: req.search_query, session_id: req.session_id } }];

const items = $input.all();
const seen = new Set();
const passages = [];
for (const it of items) {
  const t = it.json.text;
  if (!t || seen.has(t)) continue;
  seen.add(t);
  passages.push({ text: t, page: it.json.page });
}
const documents = passages.map(p => p.text);
const v = $('Vecteur vers SQL').item.json;
return [{ json: { passages, documents, question: v.question, search_query: v.search_query, session_id: v.session_id } }];

const res = $json.results || [];
const agg = $('Agreger passages').item.json;
const passages = agg.passages;
const top = res.map(r => passages[r.index]).filter(Boolean).slice(0, 5);
let context = '';
for (const p of top) { context += '[page ' + (p.page || '?') + '] ' + p.text + '\n\n'; }
return [{ json: { context, question: agg.question, session_id: agg.session_id } }];

const hist = $input.all().filter(i => i.json && i.json.question);
const top = $('Top passages').item.json;
let historyText = '';
const rows = hist.slice().reverse();
for (const h of rows) { historyText += 'Q: ' + h.json.question + '\nR: ' + h.json.answer + '\n'; }
const system = 'Tu es un assistant expert du livre Options, Futures and Other Derivatives de John Hull. Reponds en francais, uniquement a partir des EXTRAITS fournis. Cite toujours la page sous la forme (source : page X) et l extrait dont l information provient entre guillemets, accompagné d une traduction simplificatrice. Si l information n est pas dans les extraits, dis-le.';
const user = (historyText ? ('Historique:\n' + historyText + '\n') : '') + 'EXTRAITS DU LIVRE:\n' + top.context + '\nQUESTION: ' + top.question;
return [{ json: { system, user, question: top.question, session_id: top.session_id } }];
